-- ------------------------------------------------------------------------
-- 0009_audit_log.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Audit log — records actions, logins, errors, and the time each action took.
-- Clients insert their own events; the identity (user_id/email) is stamped by
-- the DB so it can't be forged. Only admins can read the log.
-- ===========================================================================

create table if not exists public.audit_log (
  id          bigint generated always as identity primary key,
  at          timestamptz not null default now(),
  user_id     uuid,
  email       text default '',
  actor       text default '',      -- display name (client-supplied)
  role        text default '',      -- role key (client-supplied)
  action      text not null,        -- e.g. login, call.create, call.report, spare.approve
  target      text default '',      -- UCN / uid / id the action acted on
  status      text default 'ok',    -- ok | error
  error       text default '',
  duration_ms integer,              -- how long the action took
  meta        jsonb not null default '{}'
);
create index if not exists audit_at_idx     on public.audit_log (at desc);
create index if not exists audit_action_idx on public.audit_log (action);
create index if not exists audit_email_idx  on public.audit_log (lower(email));
create index if not exists audit_status_idx on public.audit_log (status);

-- Stamp identity + time server-side (don't trust the client for who/when).
create or replace function public.audit_before_insert()
returns trigger language plpgsql set search_path = public as $$
begin
  new.user_id := auth.uid();
  new.email   := coalesce(nullif(auth.email(), ''), new.email);  -- keep attempted email for anon login failures
  new.at      := now();
  return new;
end $$;
drop trigger if exists audit_biu on public.audit_log;
create trigger audit_biu before insert on public.audit_log
  for each row execute function public.audit_before_insert();

alter table public.audit_log enable row level security;
-- Authenticated users log their own actions; anon may log only login attempts
-- (so failed logins, which have no session yet, are still recorded).
drop policy if exists audit_insert on public.audit_log;
create policy audit_insert on public.audit_log for insert
  with check (auth.role() = 'authenticated' or action in ('login', 'login_failed'));
-- Only admins read the audit log.
drop policy if exists audit_read on public.audit_log;
create policy audit_read on public.audit_log for select using (public.is_admin());

-- ------------------------------------------------------------------------
-- 0033_audit_retention.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Audit-log retention: keep 7 days, auto-delete anything older.
-- A daily pg_cron job runs purge_audit_log(). Safe to run in the SQL editor
-- as the `postgres` role; it enables pg_cron if it isn't already on.
-- ===========================================================================

-- Delete audit rows older than 7 days. Returns how many were removed.
create or replace function public.purge_audit_log()
returns integer
language plpgsql
security definer
set search_path = public as $$
declare removed integer;
begin
  delete from public.audit_log where at < now() - interval '7 days';
  get diagnostics removed = row_count;
  return removed;
end $$;

-- Clear one week of backlog immediately so the policy takes effect now.
select public.purge_audit_log();

-- Schedule it daily at 00:30 UTC via pg_cron.
do $$
begin
  create extension if not exists pg_cron;
exception when others then
  raise notice 'Could not enable pg_cron automatically (%). Enable it in Dashboard -> Database -> Extensions, then re-run this migration.', sqlerrm;
end $$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    -- Re-scheduling is idempotent: drop the old job first if present.
    if exists (select 1 from cron.job where jobname = 'purge-audit-log') then
      perform cron.unschedule('purge-audit-log');
    end if;
    perform cron.schedule('purge-audit-log', '30 0 * * *', 'select public.purge_audit_log();');
  else
    raise notice 'pg_cron is not enabled. Audit rows will NOT auto-delete until you enable pg_cron (Dashboard -> Database -> Extensions) and re-run this file. Until then, run: select public.purge_audit_log();';
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0047_audit_retention_compliance.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Audit-log retention for a regulated QMS. The earlier 7-day auto-delete is not
-- acceptable for medical-device quality records — the audit trail must be kept
-- for the record retention period. Retention is now a CONFIGURABLE setting,
-- defaulting to 3650 days (~10 years). The daily purge uses it. The database
-- audit trail (record_audit, 0048) is NOT purged by this job.
-- ===========================================================================

create table if not exists public.app_settings (
  key        text primary key,
  value      text not null,
  updated_at timestamptz not null default now()
);
insert into public.app_settings (key, value) values ('audit_retention_days', '3650')
  on conflict (key) do nothing;

alter table public.app_settings enable row level security;
grant select, insert, update on public.app_settings to authenticated;
drop policy if exists app_settings_read on public.app_settings;
create policy app_settings_read on public.app_settings for select using (auth.role() = 'authenticated');
drop policy if exists app_settings_write on public.app_settings;
create policy app_settings_write on public.app_settings for all
  using (public.is_admin() or public.has_perm('config.manage'))
  with check (public.is_admin() or public.has_perm('config.manage'));

-- Purge uses the configured retention (fallback 3650 days). Redefinition only —
-- the daily pg_cron job scheduled by 0033 keeps calling this function.
create or replace function public.purge_audit_log()
returns integer language plpgsql security definer set search_path = public as $$
declare removed integer; days integer;
begin
  select coalesce(nullif(value, '')::int, 3650) into days from public.app_settings where key = 'audit_retention_days';
  days := greatest(coalesce(days, 3650), 1);
  delete from public.audit_log where at < now() - make_interval(days => days);
  get diagnostics removed = row_count;
  return removed;
end $$;

-- ------------------------------------------------------------------------
-- 0114_audit_mode.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- AUDIT MODE — a switch only an administrator can throw.
--
-- Asked for by the user on 2026-09-06, WITH THE RULES TO FOLLOW: "come up with
-- an Audit Mode, which can be toggled only by the admins — I will give the list
-- of rules for that later". So this migration builds the switch and nothing
-- else. NOTHING IN THE APPLICATION READS IT YET, and that is not an oversight
-- — attaching behaviour to it before the rules arrive would mean guessing what
-- an audit is supposed to change, and guessing wrong in a regulated system is
-- worse than waiting.
--
-- WHAT IS HERE:
--   * the setting itself, in `app_settings` alongside audit_retention_days,
--     because that is where this project keeps configuration;
--   * `audit_mode()` — a stable read anything may call;
--   * `set_audit_mode()` — the only way to change it, admin-only, and it
--     refuses without a reason;
--   * `audit_mode_changes` — every flip, who and when and why, in its own
--     table.
--
-- WHY ITS OWN LOG TABLE. `audit_log` is written by the CLIENT and purged on a
-- retention window (0047). A switch that changes what the system does during an
-- audit is exactly the thing whose history must outlive both of those, so it is
-- recorded by the function itself, on the server, into a table nothing purges
-- and nobody can UPDATE or DELETE through the API. Whatever the rules turn out
-- to be, the fact that the mode was on — and for how long — will always be
-- answerable.
--
-- CLASSIFICATION. Documented in the Validation Package as a NON-AUDITABLE
-- REQUIREMENT (NAR-001), per the user's instruction. That is a statement about
-- the requirement's provenance — it is not derived from a regulatory clause and
-- is not offered as evidence of one — and NOT a statement that its use goes
-- unrecorded. Its use is recorded here, permanently.
-- ===========================================================================

-- app_settings is created by 0047 (audit module). Guarded so this file can be
-- replayed on a project where that has not run yet without dying.
do $mode$
begin
  if to_regclass('public.app_settings') is null then
    raise notice 'app_settings is missing — run 0047_audit_retention_compliance.sql first';
    return;
  end if;
  insert into public.app_settings (key, value) values ('audit_mode', 'off')
    on conflict (key) do nothing;
end $mode$;

-- ---- the log ---------------------------------------------------------------
create table if not exists public.audit_mode_changes (
  id         bigserial primary key,
  at         timestamptz not null default now(),
  turned_on  boolean     not null,
  reason     text        not null,
  changed_by uuid        references auth.users (id)
);
create index if not exists audit_mode_changes_at_idx on public.audit_mode_changes (at desc);

alter table public.audit_mode_changes enable row level security;
-- SELECT only, and only for an administrator. There is no insert/update/delete
-- policy at all, so the ONLY way a row appears is `set_audit_mode()` — a
-- SECURITY DEFINER function, which RLS does not stand in the way of. A history
-- the API cannot edit is the point of the table.
grant select on public.audit_mode_changes to authenticated;
revoke insert, update, delete on public.audit_mode_changes from authenticated;
drop policy if exists amc_read on public.audit_mode_changes;
create policy amc_read on public.audit_mode_changes for select
  using (public.is_admin() or public.has_perm('audit.view'));

-- ---- read ------------------------------------------------------------------
create or replace function public.audit_mode()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(
    (select lower(btrim(value)) in ('on', 'true', '1', 'yes')
       from public.app_settings where key = 'audit_mode'),
    false)
$$;
revoke all on function public.audit_mode() from public;
grant execute on function public.audit_mode() to authenticated;

-- ---- write -----------------------------------------------------------------
-- Admin only, by the user's instruction. Not `config.manage`, which is what
-- app_settings' own write policy allows: the user said ADMINS, and a switch is
-- not a retention number.
create or replace function public.set_audit_mode(p_on boolean, p_reason text)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_now boolean;
begin
  if not public.is_admin() then
    raise exception 'RBAC: only an administrator can change Audit Mode';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Changing Audit Mode needs a reason';
  end if;

  v_now := public.audit_mode();
  if v_now is not distinct from p_on then
    -- Not an error, and not a log entry either: recording "changed from off to
    -- off" would pad the history that the history exists to keep readable.
    return v_now;
  end if;

  insert into public.app_settings (key, value, updated_at)
       values ('audit_mode', case when p_on then 'on' else 'off' end, now())
  on conflict (key) do update set value = excluded.value, updated_at = excluded.updated_at;

  insert into public.audit_mode_changes (turned_on, reason, changed_by)
       values (p_on, btrim(p_reason), auth.uid());

  return p_on;
end $$;
revoke all on function public.set_audit_mode(boolean, text) from public;
grant execute on function public.set_audit_mode(boolean, text) to authenticated;

comment on table public.audit_mode_changes is
  'Every change of Audit Mode: on/off, why, who, when. Written only by set_audit_mode(); never purged, never editable through the API.';

commit;
